function applyTheme(){const t=state.settings.theme;document.documentElement.dataset.theme=t==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):t;}
function toast(text){const n=document.getElementById('toast');n.textContent=text;n.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>n.classList.remove('show'),3400);}
function pill(text,color=''){return `<span class="pill ${color}">${esc(text)}</span>`;}
function button(text,action,cls='',ic='',more=''){const accessible=text.replace(/<[^>]*>/g,'').trim();return `<button type="button" class="btn ${cls}" aria-label="${esc(accessible)}" data-action="${action}" ${more}>${ic?icon(ic):''}${text}</button>`;}
function pageHeading(title,sub,actions='',eyebrow='PROJECT WORKSPACE'){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="sub">${sub}</p></div>${actions?`<div class="actions">${actions}</div>`:''}</div>`;}
