function directionPage(){const p=project();return `${pageHeading('方向清楚，推进才有依据。','定义你希望产品变成什么样，AI 负责拆解并推进具体工作。',button('调整方向','edit-direction','primary','sliders'),'DIRECTION & BOUNDARIES')}<div class="direction-layout"><div class="stack"><section class="card card-pad"><div class="row between"><span class="eyebrow">当前方向</span>${pill('版本 '+p.version,'green')}</div><h2 style="font-size:21px;line-height:1.7;margin:17px 0 12px">${esc(p.direction)}</h2><p class="small muted">${esc(p.detail)}</p><div class="separator"></div><h3>AI 如何理解这个方向</h3><div class="criteria">${icon('target')}<span><b>首先改善核心使用流程</b><br>从接入数据到完成第一次分析，优先减少明确的使用障碍。</span></div><div class="criteria">${icon('shield')}<span><b>结果可靠性保持不变</b><br>原始数据不能丢失，不用隐瞒失败来提高完成率。</span></div><div class="criteria">${icon('activity')}<span><b>用实际结果验证改善</b><br>工程检查与上线效果分别记录；证据不足时继续观察。</span></div><div class="help-box">这些目标解释由 AI 根据方向推导。你可以随时纠正，具体需求和研发计划由 AI 自主调整。</div></section><section class="card"><div class="card-head"><h2>方向变更记录</h2><span class="tiny muted">变更影响后续计划</span></div><div class="card-pad change-log"><div class="item"><span class="version">v${p.version}</span><div><p class="strong" style="color:var(--ink)">${esc(p.direction)}</p><p>当前生效 · ${p.isNew?'刚刚建立':p.version>3?'刚刚更新':'今天 08:30'}</p></div></div><div class="item" style="${p.isNew?'display:none':''}"><span class="version">v2</span><p>先改善首次分析的核心路径，减少非必要新功能。</p></div><div class="item" style="${p.isNew?'display:none':''}"><span class="version">v1</span><p>接入现有项目，建立产品使用与运行状态基线。</p></div></div></section></div><div class="stack"><section class="card card-pad"><div class="section-title"><h2>自主推进边界</h2>${icon('shield')}</div><div class="list-line"><div class="row between small"><span>常规改进与问题修复</span>${pill('自主交付','green')}</div><p class="tiny muted" style="margin-top:8px;line-height:1.9">在现有产品范围内设计、开发、验证与发布。</p></div><div class="list-line"><div class="row between small"><span>新增外部服务与授权</span>${pill('需要方向调整','amber')}</div><p class="tiny muted" style="margin-top:8px;line-height:1.9">涉及新费用、新账号权限或服务范围变化。</p></div><div class="list-line"><div class="row between small"><span>资源预算</span><span class="mono">¥${state.budget} / 天</span></div><p class="tiny muted" style="margin-top:8px;line-height:1.9">接近上限后停止新任务，在可恢复边界保存进度。</p></div></section><section class="card card-pad"><div class="eyebrow">什么时候会来找你</div><div class="criteria">${icon('compass')}<span>产品方向存在冲突或需要改变。</span></div><div class="criteria">${icon('key')}<span>需要扩大授权或增加资源预算。</span></div><div class="criteria">${icon('alert')}<span>现有边界内无法继续，需要重新取舍。</span></div><p class="tiny muted" style="line-height:1.9">实现方案、代码审查与常规发布留在系统内部完成。</p></section></div></div>`;}
function decisionsPage(){return `${projectLeads()}${pageHeading('知道它为什么往这里走。','每项工作都关联目标、来源证据与预期改善。',button('调整方向','edit-direction','','compass'),'DECISION JOURNAL')}<div class="filter-bar"><span class="filter-chip active">全部决策</span><span class="tiny muted">按最近更新时间排列</span></div>${!state.directionAnswered?`<section class="decision-inbox" style="margin-bottom:20px"><div class="row between wrap"><div><div class="eyebrow">等待方向取舍</div><h3>是否把图片账单纳入当前产品范围？</h3><p>新增付费 OCR 影响费用与数据处理边界。</p></div>${button('查看取舍','strategic','','compass')}</div></section>`:''}<section class="card">${tasks.map((t,i)=>`<button class="decision-card" data-action="task-detail" data-task="${t.id}"><span class="decision-number">0${i+1}</span><div><div class="title">${t.title}</div><p class="desc">${t.why}</p><div class="evidence"><span>${t.evidence.length} 组来源证据</span><span>关联当前方向</span><span>${i===0?'高优先级':'计划已记录'}</span></div></div>${pill(t.statusText,t.status==='running'?'green':'')}</button>`).join('')}</section>`;}
function tasksPage(){const filtered=taskFilter==='all'?tasks:tasks.filter(t=>t.status===taskFilter);return `${pageHeading('研发持续推进，过程随时可查。','任务由 AI 从目标和反馈中产生，按验证结果进入下一阶段。',button(state.paused?'恢复新任务':'暂停新任务','toggle-pause',state.paused?'primary':'',state.paused?'play':'pause'),'DEVELOPMENT FLOW')}<div class="filter-bar">${[['all','全部工作',4],['running','正在推进',1],['planned','待推进',1],['shipped','已交付',2]].map(([k,t,n])=>`<button class="filter-chip ${taskFilter===k?'active':''}" data-action="task-filter" data-filter="${k}" aria-pressed="${taskFilter===k}">${t} <span style="margin-left:6px;opacity:.65">${n}</span></button>`).join('')}</div><section class="card table-wrap"><table class="task-table"><thead><tr><th>工作项</th><th>当前阶段</th><th>来源</th><th>更新时间</th><th></th></tr></thead><tbody>${filtered.map(t=>`<tr data-action="task-detail" data-task="${t.id}"><td><button class="task-title" data-action="task-detail" data-task="${t.id}">${t.title}</button><div class="task-sub">${t.kind} · #${t.id.slice(1)}</div></td><td>${pill(state.paused&&t.status==='running'?'已请求暂停':t.statusText,t.status==='running'?'green':t.status==='planned'?'':'')}</td><td class="muted">用户反馈与运行数据</td><td class="mono muted">${t.time}</td><td class="table-action">${icon('chevron')}</td></tr>`).join('')}</tbody></table></section><div class="help-box" style="margin-top:20px">暂停新任务时，现有工作在可恢复边界结束。查看执行详情可单独请求停止当前工作。</div>`;}
function deliveriesPage(){return `${pageHeading('交付之后，继续看结果。','代码检查通过、部署成功、业务效果改善，分别保留证据。','','DELIVERIES & OUTCOMES')}<div class="grid3" style="margin-bottom:21px"><section class="card card-pad"><span class="eyebrow">本周交付</span><h2 style="font-size:27px;margin:10px 0 5px">14 <span class="small muted">项</span></h2><p class="tiny muted">示例：所有交付都有独立验证记录</p></section><section class="card card-pad"><span class="eyebrow">已完成效果评估</span><h2 style="font-size:27px;margin:10px 0 5px">11 <span class="small muted">项</span></h2><p class="tiny muted">有改善、无变化与退化都被保留</p></section><section class="card card-pad"><span class="eyebrow">等待更多样本</span><h2 style="font-size:27px;margin:10px 0 5px">3 <span class="small muted">项</span></h2><p class="tiny muted">保持观察，不提前宣称目标达成</p></section></div><section class="card">${[tasks[1],tasks[2]].map((t,i)=>`<article class="release-large"><div class="row between wrap"><div class="row">${pill(i===0?'发布后观察':'效果已评估',i===0?'':'green')}<span class="mono muted">${i===0?(state.releaseRestored?'v0.9.11 · 已演示恢复':'v0.9.12'):'v0.9.11'}</span></div><span class="tiny muted">${i===0?'今天 09:18':'昨天 17:26'}</span></div><div class="title">${t.title}</div><p>${t.summary}</p><div class="checks"><span>${icon('check')}独立检查通过</span><span>${icon('check')}浏览器流程通过</span><span>${icon('check')}上线运行正常</span></div><div class="release-actions"><span class="tiny muted">${i===0?'目标效果：样本积累中，暂无充分结论。':'示例效果：用户重复无效重试减少。'}</span><div class="row">${i===0?button('恢复方案','release-recovery','ghost','history'):''}${button('查看交付证据','task-detail','','arrow',`data-task="${t.id}" data-tab="verification"`)}</div></div></article>`).join('')}</section><p class="bottom-note">${icon('info')}交付数据与效果均为界面示例，尚未接入真实项目。</p>`;}
function knowledgePage(){const items=[{status:'adopted',tag:'已采用',title:'导入失败时，保留原始字段与已确认进度',desc:'此前两次修复只解决了格式识别，用户仍需重新选择文件。新增检查要求同时验证数据与操作进度是否保留。',source:'来自 2 次返工 · 3 组回归样本',when:'今天 08:10'}, {status:'testing',tag:'验证中',title:'错误提示必须能对应用户实际看到的页面',desc:'技术日志正确并不代表界面能帮助用户解决问题。候选规则要求在使用界面上复现问题，再检查修复结果。',source:'来自 4 条反馈 · 历史案例回放中',when:'今天 07:40'}, {status:'candidate',tag:'待验证',title:'对日期与时区相关行为固定所有读取时钟',desc:'一个示例测试只固定了业务时间，统计窗口仍使用系统日期。规则候选将通过历史用例和跨时区回放验证。',source:'来自 1 次验证偏差 · 尚未生效',when:'昨天 21:06'}];const filtered=lessonFilter==='all'?items:items.filter(x=>x.status===lessonFilter);return `${pageHeading('每一次返工，都留下可验证的经验。','项目事实、决策和工作规则分别保存，候选经验验证后再生效。','','PROJECT MEMORY')}<div class="filter-bar">${[['all','全部经验'],['adopted','已采用'],['testing','验证中'],['candidate','候选']].map(([k,v])=>`<button class="filter-chip ${lessonFilter===k?'active':''}" data-action="lesson-filter" data-filter="${k}" aria-pressed="${lessonFilter===k}">${v}</button>`).join('')}</div><section class="card">${filtered.map(x=>`<article class="lesson"><div class="row between"><span class="eyebrow">工作方式改进</span>${pill(x.tag,x.status==='adopted'?'green':x.status==='testing'?'amber':'')}</div><div class="title" style="margin-top:13px">${x.title}</div><p class="desc">${x.desc}</p><div class="footer"><span>${x.source}</span><span>${x.when}</span></div></article>`).join('')}</section><div class="help-box" style="margin-top:20px">经验采用不改变人的方向、资源上限或本轮验收条件。任何改进都保留来源与验证结果。</div>`;}
function runtimePage(){return `${pageHeading('工作可以持续，环境可以更换。','查看本地服务、后台任务与运行包状态。以下为升级流程示例。',button('查看桌面设计','navigate','','info','data-view="notes"'),'RUNTIME & DESKTOP')}<div class="runtime-grid"><section class="card card-pad"><div class="runtime-head"><div class="device-icon">${icon('monitor')}</div><div class="grow"><h2>本地执行环境</h2><p class="tiny muted" style="margin-top:6px">桌面宿主：Tauri 2 · 方案候选</p></div>${pill('示例在线','green')}</div><div class="runtime-facts"><div><label>执行引擎</label><div class="value">DeepSeek Harness</div></div><div><label>当前新任务运行包</label><div class="value">示例包 ${state.activePack}</div></div><div><label>当前执行中的工作</label><div class="value">${project().isNew?'0 个 · 本项目尚未连接':'1 个 · 绑定示例包 A'}</div></div><div><label>恢复方式</label><div class="value">项目状态与检查点</div></div></div><div class="separator"></div><p class="tiny muted" style="line-height:1.9">执行中的工作保持原运行包。切换只影响后续新任务，原生会话空间彼此分离。</p><div style="margin-top:17px">${button('查看当前执行','task-detail','','terminal','data-task="r128" data-tab="logs"')}</div></section><section class="card"><div class="card-head"><h2>运行包管理</h2>${pill('演示流程')}</div><div class="card-pad" style="padding-top:0;padding-bottom:5px"><div class="package-row"><span class="package-icon">${icon('box')}</span><div class="grow"><h3>示例包 A</h3><p>基线运行包 · 保留恢复能力</p></div>${state.activePack==='A'?pill('当前使用','green'):button('恢复路由','rollback-runtime','ghost')}</div><div class="package-row"><span class="package-icon">${icon('box')}</span><div class="grow"><h3>示例包 B</h3><p>${state.activePack==='B'?'新任务已切换，旧任务继续运行':state.candidateReady?'候选验证演示完成，等待切换':'候选运行包，尚待验证'}</p></div>${state.activePack==='B'?pill('当前使用','green'):button(state.candidateReady?'切换新任务':'演示验证',state.candidateReady?'upgrade-runtime':'validate-runtime',state.candidateReady?'primary':'')}</div></div></section></div><section class="card card-pad" style="margin-top:22px"><div class="section-title"><h2>后台运行与恢复</h2>${icon('leaf')}</div><div class="grid3"><div><h3 class="small">关闭窗口</h3><p class="tiny muted" style="margin-top:9px;line-height:1.9">按偏好进入托盘后台；界面可以休息，工作继续推进。</p>${button('体验收起窗口','window-minimize','ghost','monitor')}</div><div><h3 class="small">真正退出</h3><p class="tiny muted" style="margin-top:9px;line-height:1.9">在可恢复边界结束工作，保存状态并关闭执行进程。</p>${button('体验保存与退出','quit-dialog','ghost','exit')}</div><div><h3 class="small">版本升级</h3><p class="tiny muted" style="margin-top:9px;line-height:1.9">候选验证后切换新任务，发现退化可恢复路由。</p>${button('查看升级原则','upgrade-info','ghost','refresh')}</div></div></section>`;}
function settingsPage(){return `${pageHeading('让它按你的习惯持续工作。','桌面行为、通知和资源偏好自动保存到当前浏览器。','','PREFERENCES')}<div class="settings-group card"><div class="card-head"><h2>桌面与后台</h2>${icon('monitor')}</div><div class="card-pad"><div class="toggle-row"><div><div class="title">关闭窗口时</div><p class="desc">窗口关闭与真正退出分别处理。</p></div><select class="settings-select" data-setting="close" aria-label="关闭窗口时的行为"><option value="background" ${state.settings.close==='background'?'selected':''}>进入后台继续工作</option><option value="ask" ${state.settings.close==='ask'?'selected':''}>每次选择</option><option value="checkpoint" ${state.settings.close==='checkpoint'?'selected':''}>保存进度并退出</option></select></div><div class="toggle-row"><div><div class="title">登录系统时启动</div><p class="desc">桌面实现规格；原型只保存偏好，不修改系统。</p></div><input class="switch" type="checkbox" data-setting="autostart" aria-label="登录系统时启动" ${state.settings.autostart?'checked':''}></div><div class="toggle-row"><div><div class="title">重启后恢复未完成工作</div><p class="desc">先核对原有执行状态，避免重复交付。</p></div><input class="switch" type="checkbox" data-setting="resume" aria-label="重启后恢复工作" ${state.settings.resume?'checked':''}></div></div></div><div class="settings-group card"><div class="card-head"><h2>外观与通知</h2>${icon('light')}</div><div class="card-pad"><div class="toggle-row"><div><div class="title">界面外观</div><p class="desc">同一套页面适配浅色、深色与系统外观。</p></div><select class="settings-select" data-setting="theme" aria-label="界面外观"><option value="light" ${state.settings.theme==='light'?'selected':''}>浅色</option><option value="dark" ${state.settings.theme==='dark'?'selected':''}>深色</option><option value="system" ${state.settings.theme==='system'?'selected':''}>跟随系统</option></select></div><div class="toggle-row"><div><div class="title">需要方向取舍时提醒我</div><p class="desc">方向冲突、预算扩大和新增授权。</p></div><input class="switch" type="checkbox" data-setting="notify" aria-label="方向取舍通知" ${state.settings.notify?'checked':''}></div><div class="toggle-row"><div><div class="title">日常研发保持安静</div><p class="desc">实现、验证和发布结果汇总到项目中，避免频繁打断。</p></div><input class="switch" type="checkbox" data-setting="quiet" aria-label="日常研发保持安静" ${state.settings.quiet?'checked':''}></div></div></div><div class="settings-group card"><div class="card-head"><h2>资源与原型</h2>${icon('sliders')}</div><div class="card-pad"><div class="toggle-row"><div><div class="title">每日资源上限</div><p class="desc">用于本原型的预算展示，不会产生实际费用。</p></div><label class="budget-input"><span>¥</span><input type="number" min="15" max="10000" value="${state.budget}" data-setting="budget" aria-label="每日资源预算"></label></div><div class="toggle-row"><div><div class="title">桌面设计与产品原则</div><p class="desc">查看接入边界、生命周期与性能要求。</p></div>${button('查看说明','navigate','ghost','arrow','data-view="notes"')}</div><div class="toggle-row"><div><div class="title">清除原型演示状态</div><p class="desc">恢复初始示例，不影响任何真实文件或项目。</p></div>${button('恢复示例','reset-demo','ghost','refresh')}</div></div></div>`;}
function notesPage(){return shellDesignNotes();}
function renderProjectMenu(){return `<div class="project-popover" role="menu" aria-label="选择工作空间">${state.projects.map(p=>`<button class="project-option" data-action="switch-project" data-project="${esc(p.id)}" role="menuitem">${icon('folder')}<span class="grow">${esc(p.name)}</span>${p.id===state.activeProject?icon('check','class="check"'):''}</button>`).join('')}<div class="separator" style="margin:5px 0"></div><button class="project-option" data-action="new-workspace" role="menuitem">${icon('plus')}添加工作空间</button></div>`;}
function openOverlay(html,type='modal'){lastFocus=document.activeElement;overlay=type;document.getElementById('overlay-root').innerHTML=html;const n=document.querySelector('#overlay-root input:not([type="radio"]), #overlay-root textarea, #overlay-root button');n?.focus();}
function closeOverlay(){document.getElementById('overlay-root').innerHTML='';overlay=null;if(lastFocus?.isConnected)lastFocus.focus();else document.querySelector('.tree-session.active,.autonomy-tree-row.active,.shell-nav .active')?.focus();}
function modal(title,sub,body,foot='',large=false){openOverlay(`<div class="overlay" data-backdrop="close"><section class="modal ${large?'large':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-head"><div><h2 id="modal-title">${title}</h2>${sub?`<p>${sub}</p>`:''}</div><button class="icon-btn" data-action="close-overlay" aria-label="关闭弹窗">${icon('close')}</button></header><div class="modal-body">${body}</div>${foot?`<footer class="modal-foot">${foot}</footer>`:''}</section></div>`);}
function editDirection(){const p=project();modal('调整产品方向','AI 将据此重新评估未开始的工作与当前计划。',`<form id="direction-form"><div class="field"><label for="direction-input">你希望产品朝哪里走？</label><textarea id="direction-input" name="direction" rows="3" required maxlength="240">${esc(p.direction)}</textarea><p class="hint">描述用户、希望解决的问题与优先级，具体需求由 AI 调查和拆解。</p></div><div class="field"><label for="direction-detail">优先级与底线</label><textarea id="direction-detail" name="detail" rows="3" maxlength="500">${esc(p.detail)}</textarea></div><div class="field"><label for="direction-budget">每日资源预算（示例）</label><div class="budget-input"><span>¥</span><input id="direction-budget" name="budget" type="number" min="15" max="10000" value="${state.budget}" required></div></div><div class="help-box">范围内的设计、开发、验证和发布继续由 AI 自主完成。需要新增授权或改变方向时再与你同步。</div><p id="direction-error" class="form-error" role="alert"></p></form>`,`<span class="note">将生成方向版本 v${p.version+1}</span>${button('取消','close-overlay') }<button class="btn primary" type="submit" form="direction-form">保存方向 ${icon('arrow')}</button>`);}
function taskDetail(id,tab='decision'){drawerTask=id;drawerTab=tab;const t=tasks.find(x=>x.id===id)||tasks[0];const tabLabels=[['decision','决策依据'],['changes','代码变更'],['verification','独立验证'],['logs','执行日志']];let body='';if(tab==='decision')body=`<section class="drawer-section"><h3>为什么优先做这件事</h3><p>${t.why}</p><div class="reason-card"><div class="reason-title">与当前方向的关系</div><p>${esc(project().direction)}。这项工作从已有障碍入手，保持结果可靠性。</p></div></section><section class="drawer-section"><h3>依据来自哪里</h3>${t.evidence.map((e,i)=>`<div class="evidence-row">${icon(i===1?'file':'activity')}<span class="grow">${e}</span>${pill('示例来源')}</div>`).join('')}</section><section class="drawer-section"><h3>预期改变与验收</h3>${t.changes.map(c=>`<div class="criteria">${icon('check')}<span>${c}</span></div>`).join('')}<p style="margin-top:11px">${t.outcome}</p></section>`;
if(tab==='changes')body=`<section class="drawer-section"><h3>变更范围</h3><p>${t.summary}</p><div class="file-list">${t.files.map(f=>`<span class="file-tag">${esc(f)}</span>`).join('')}</div><div class="row between tiny muted"><span>示例代码片段</span><span>+18 −4</span></div><div class="diff"><span class="diff-line head">@@ src/import/header.ts · 示例 @@</span><span class="diff-line remove">− const name = column.trim();</span><span class="diff-line add">+ const original = column;</span><span class="diff-line add">+ const normalized = normalizeHeader(column);</span><span class="diff-line add">+ const name = aliases[normalized] ?? normalized;</span><span class="diff-line">  return { name, original };</span></div></section><div class="help-box">显示与本次决策关联的变更，完整差异在真实客户端中由 Git 工作区提供。</div>`;
if(tab==='verification')body=`<section class="drawer-section"><div class="row between"><h3>按本轮验收条件独立检查</h3>${pill(t.status==='stopped'?'已停止':t.status==='planned'?'尚未开始':t.status==='running'?'进行中':'已通过',t.status==='running'?'amber':'green')}</div>${t.checks.length?t.checks.map(([n,r])=>`<div class="check-row">${icon(r.includes('验证中')?'clock':'check')}<span>${n}</span><span class="duration">${r}</span></div>`).join(''):'<p>任务开始前先冻结本轮验收条件。</p>'}</section><section class="drawer-section"><h3>工程与业务效果分别记录</h3><div class="reason-card"><div class="reason-title">${t.status==='shipped'?'部署状态：已上线（示例）':'部署状态：尚未发布'}</div><p>${t.outcome}</p></div></section><p>当前界面是设计示例。真实验证结果将关联代码版本、构建产物、检查执行器与原始日志。</p>`;
if(tab==='logs')body=`<div class="row between" style="margin-bottom:13px"><h3 style="margin:0">执行记录</h3>${pill('示例日志')}</div><div class="terminal" aria-label="示例执行日志">${[['09:31:04','读取目标版本 v3 与当前项目快照','dim'],['09:31:06','检查仓库与已存在的导入测试',''],['09:32:12','复现失败样本：非标准表头',''],['09:33:41','保留原始列名，建立别名映射',''],['09:36:08','完成候选实现，移交独立验证','success'],['09:37:19','PASS  表头别名映射（14 项）','success'],['09:38:26','PASS  空字段与重复字段（8 项）','success'],['09:39:52','PASS  原有导入回归（26 项）','success'],['09:42:10','浏览器使用流程验证中…',''],['09:42:10','暂无发布结论，等待检查证据','dim']].map(([time,msg,cls])=>`<div class="terminal-line ${cls}"><span class="stamp">${time}</span>${msg}</div>`).join('')}</div><p style="margin-top:15px">原生客户端按事件增量传输和按需读取日志，避免把全部历史长期放进界面。</p>`;
openOverlay(`<div class="overlay drawer-overlay" data-backdrop="close"><section class="drawer" role="dialog" aria-modal="true" aria-labelledby="drawer-title"><header class="drawer-head"><div class="row between"><span class="mono muted">WORK #${t.id.slice(1)} · ${t.kind}</span><button class="icon-btn" data-action="close-overlay" aria-label="关闭执行详情">${icon('close')}</button></div><h2 id="drawer-title">${t.title}</h2><div class="row between"><span class="mono muted">${t.branch}</span>${pill(t.statusText,t.status==='running'?'green':'')}</div></header><div class="subnav" role="tablist" aria-label="执行详情">${tabLabels.map(([k,n])=>`<button data-action="drawer-tab" data-tab="${k}" role="tab" aria-selected="${tab===k}" class="${tab===k?'active':''}">${n}</button>`).join('')}</div><div class="drawer-body" role="tabpanel">${body}</div><footer class="drawer-footer">${button('打开 Harness 会话','open-task-session','ghost','terminal','data-task="'+t.id+'"')}<span class="mono">${t.sha==='—'?'代码尚未产生':'SHA '+t.sha} · 方向 v${project().version}</span>${t.status==='running'?button('停止当前工作','stop-task','ghost','pause'):button('查看方向','drawer-direction','ghost','compass')}</footer></section></div>`,'drawer');}
function strategic(){modal('是否支持图片账单？','这项变化涉及新的外部服务与费用，属于方向层面的取舍。',`<section class="drawer-section"><h3>AI 发现了什么</h3><p class="small muted" style="margin-top:9px">示例反馈中有 3 位商家希望上传图片账单。支持这一能力需要引入 OCR 服务，增加调用费用，也扩大数据处理范围。</p></section><section class="drawer-section"><h3>AI 的建议</h3><div class="reason-card"><div class="reason-title">优先修好现有表格流程，暂不扩展范围。</div><p class="small muted">当前首次分析的主要障碍仍是表头与缺失字段，已有数据可以支持更明确的改进。</p></div></section><form id="strategic-form"><label class="radio-option"><input type="radio" name="strategy" value="keep" checked><span>保持现有范围与预算<p>继续改进表格导入，将图片账单保留在未来机会中。</p></span></label><label class="radio-option"><input type="radio" name="strategy" value="explore"><span>允许小范围调研，实施前再明确授权<p>AI 先调查方案、费用与数据流转，不启用付费服务。</p></span></label></form>`,`${button('稍后再看','close-overlay')}<button class="btn primary" type="submit" form="strategic-form">更新方向与边界 ${icon('check')}</button>`);}
function commandPalette(){openOverlay(`<div class="overlay" data-backdrop="close"><section class="modal palette" role="dialog" aria-modal="true" aria-label="搜索与快捷操作"><div class="palette-search">${icon('search')}<input id="command-input" aria-label="搜索页面或操作" placeholder="跳转页面，或者调整方向…" autocomplete="off"><button class="icon-btn" data-action="close-overlay" aria-label="关闭搜索">${icon('close')}</button></div><div id="palette-results" class="palette-results">${paletteResults('')}</div><div class="palette-footer">Esc 关闭　·　所有操作仅作用于当前原型</div></section></div>`,'command');}
function paletteResults(q){return shellPaletteResults(q);}
function notifications(){if(!project().direction||project().isNew){modal('与你有关的更新','当前工作空间暂无通知。',`<p class="small muted">会话与项目的更新跟随各自的工作空间保存。</p>`,button('关闭','close-overlay','primary'));return;}openOverlay(`<div class="overlay drawer-overlay" data-backdrop="close"><section class="drawer" role="dialog" aria-modal="true" aria-labelledby="drawer-title"><header class="drawer-head"><div class="row between"><h2 id="drawer-title" style="margin:0">与你有关的更新</h2><button class="icon-btn" data-action="close-overlay" aria-label="关闭通知">${icon('close')}</button></div><p style="margin-top:10px">日常工作安静推进，需要方向取舍时再打扰。</p></header><div class="drawer-body notice-list">${!state.directionAnswered?`<article class="notice"><span class="notice-icon">${icon('compass')}</span><div><div class="title">图片账单需要一次范围取舍</div><p>新增 OCR 会涉及费用与数据流转，AI 建议先改善现有表格流程。</p><button class="link" data-action="strategic">查看取舍 ${icon('arrow')}</button><div class="time">今天 09:40 · 示例</div></div></article>`:''}<article class="notice"><span class="notice-icon">${icon('box')}</span><div><div class="title">一项改进已交付，正在积累效果样本</div><p>导入中断后可以恢复，工程与浏览器验证均已通过。</p><button class="link" data-action="task-detail" data-task="r127" data-tab="verification">查看交付 ${icon('arrow')}</button><div class="time">今天 09:18 · 示例</div></div></article><article class="notice"><span class="notice-icon">${icon('book')}</span><div><div class="title">项目采用了一条已验证的经验</div><p>修复导入流程时，同时验证原始数据与操作进度是否保留。</p><div class="time">今天 08:10 · 示例</div></div></article></div></section></div>`,'drawer');}
function newProject(){projectMenu=false;render();modal('接入一个已有项目','给出项目位置与方向，AI 再调查代码、环境和当前状态。',`<form id="project-form"><div class="field"><label for="project-name">项目名称</label><input id="project-name" name="name" placeholder="例如：经营分析助手" maxlength="50" required></div><div class="field"><label for="project-path">项目位置（原型示例）</label><div class="project-path-input"><input id="project-path" name="path" placeholder="~/Projects/your-project" required><button type="button" class="btn" data-action="sample-directory">示例目录</button></div><p class="hint">真实桌面端通过系统目录选择器授权；此原型不会访问文件。</p></div><div class="field"><label for="project-direction">你希望它朝哪里改进？</label><textarea id="project-direction" name="direction" rows="3" placeholder="描述用户、目标与当前优先级…" maxlength="240" required></textarea></div><p id="project-error" class="form-error" role="alert"></p></form>`,`${button('取消','close-overlay')}<button class="btn primary" form="project-form" type="submit">创建示例项目 ${icon('arrow')}</button>`);}
function renderTray(){document.getElementById('app').innerHTML=`<main class="tray-screen"><section class="tray-card"><div class="brand-mark">${icon('compass')}</div><div class="eyebrow">${exited?'CHECKPOINT SAVED':'BACKGROUND MODE'}</div><h1 style="margin-top:8px">${exited?'进度已保存，可以安心离开。':'窗口收起，项目继续向前。'}</h1><p>${exited?'原型已模拟保存项目状态并结束执行。再次打开时，会先核对检查点，再恢复允许继续的工作。':'原型模拟托盘状态：界面停止高频渲染，Agent Service 保持工作。重新打开窗口即可回到原来的项目。'}</p><div class="tray-running"><div class="row"><span class="dot ${exited?'gray':state.paused?'amber':''}"></span><span>${exited?'检查点已保存':state.paused?'新任务已暂停':'仍在处理：非标准表头识别验证'}</span></div><p class="tiny muted" style="margin:7px 0 0">${esc(project().name)} · 方向 v${project().version}</p></div>${button(exited?'重新打开工作台':'返回工作台','restore-window','primary','arrow')}${!exited?button('保存进度并退出','quit-dialog','ghost','exit'):''}<div class="demo-note">这是窗口生命周期的交互模拟，不是真实的系统托盘。</div></section></main>`;}
function closeWindow(){if(state.settings.close==='background'){background=true;render();}else if(state.settings.close==='checkpoint'){exited=true;persist();render();}else{modal('关闭窗口后，工作如何继续？','你可以在偏好设置中保存默认行为。',`<div class="help-box">进入后台后，AI 在既定方向和资源范围内继续推进；真正退出则保存检查点并结束执行。</div>`,`${button('取消','close-overlay')}${button('保存并退出','quit-now','','exit')}${button('进入后台','background-now','primary','monitor')}`);}}
function handleAction(el){const a=el.dataset.action;if(!a)return;if(handleSelfAction(el))return;if(handleShellAction(el))return;const previousOverlay=overlay;
 switch(a){
 case 'navigate':view=el.dataset.view;projectMenu=false;closeOverlay();render();break;
 case 'palette-navigate':view=el.dataset.view;closeOverlay();render();break;
 case 'project-menu':projectMenu=!projectMenu;render();break;
 case 'switch-project':activateWorkspace(el.dataset.project);projectMenu=false;view='workbench';persist();render();break;
 case 'new-project':newProject();break;
 case 'open-autonomy':if(project().direction){view='overview';closeOverlay();render();}else enableAutonomy();break;
 case 'edit-direction':projectMenu=false;editDirection();break;
 case 'project-setup-info':modal('建立项目基线','原生桌面端接入后执行，当前只展示准备流程。',`<div class="criteria">${icon('folder')}<span>通过系统目录选择授权访问项目。</span></div><div class="criteria">${icon('search')}<span>调查代码、测试、部署与现有产品状态。</span></div><div class="criteria">${icon('target')}<span>建立指标基线，形成可验证的候选工作。</span></div><div class="help-box">此原型未连接执行环境，不会扫描目录或生成真实研发任务。</div>`,button('明白了','close-overlay','primary'));break;
 case 'toggle-pause':state.paused=!state.paused;project().paused=state.paused;persist();if(previousOverlay)closeOverlay();render();toast(state.paused?'已暂停新任务。现有工作将在可恢复边界结束。':'已恢复自主推进。');break;
 case 'task-detail':taskDetail(el.dataset.task||'r128',el.dataset.tab||'decision');break;
 case 'drawer-tab':taskDetail(drawerTask,el.dataset.tab);break;
 case 'drawer-direction':closeOverlay();view='direction';render();break;
 case 'task-filter':taskFilter=el.dataset.filter;render();break;
 case 'lesson-filter':lessonFilter=el.dataset.filter;render();break;
 case 'strategic':strategic();break;
 case 'close-overlay':closeOverlay();break;
 case 'command':projectMenu=false;commandPalette();break;
 case 'notifications':notifications();break;
 case 'sample-directory':document.getElementById('project-path').value='~/Projects/new-commerce-app';toast('已填入示例目录；未访问本地文件。');break;
 case 'window-close':closeWindow();break;
 case 'window-minimize':closeOverlay();background=true;render();break;
 case 'background-now':closeOverlay();background=true;render();break;
 case 'restore-window':background=false;exited=false;closeOverlay();render();toast('已从保存的原型状态恢复工作台。');break;
 case 'window-expand':toast('原型会随浏览器宽度适配；原生客户端由系统窗口管理。');break;
 case 'quit-dialog':modal('保存进度并退出？','这是退出行为的原型演示，不会关闭你的浏览器。',`<p class="small muted">系统将在可恢复边界结束工作，保存任务与已确认的外部动作，再关闭执行进程。下次打开时先核对状态。</p>`,`${button('继续使用','close-overlay')}${button('保存并退出','quit-now','primary','exit')}`);break;
 case 'quit-now':closeOverlay();exited=true;background=false;persist();render();break;
 case 'stop-task':modal('停止当前工作','已完成的变更与检查记录会保留，停止本项不会改变产品方向。',`<p class="small muted">原生实现先请求有界停止，再核对执行进程与工作区状态。这个原型会模拟暂停新任务与保存执行检查点。</p>`,`${button('继续执行','close-overlay')}${button('请求停止','confirm-stop','danger','pause')}`);break;
 case 'confirm-stop':stopWorkItem(drawerTask);closeOverlay();render();toast('本轮已演示停止，检查点保留；项目可重新评估后续工作。');break;
 case 'validate-runtime':state.candidateReady=true;persist();render();toast('候选包验证已演示完成；这里没有执行真实兼容测试。');break;
 case 'upgrade-runtime':state.activePack='B';persist();render();toast('新任务路由已演示切到 B，当前工作仍使用 A。');break;
 case 'rollback-runtime':state.activePack='A';persist();render();toast('新任务已恢复到示例包 A，项目状态保持不变。');break;
 case 'upgrade-info':modal('升级以运行包为单位','宿主、业务协议与 Harness 扩展分别保留兼容边界。',`<div class="criteria">${icon('check')}<span>先构建并验证候选运行包，保留工具与权限清单。</span></div><div class="criteria">${icon('check')}<span>旧工作继续使用原包，新任务逐步切换。</span></div><div class="criteria">${icon('check')}<span>不同原生会话空间隔离，通过项目状态交接。</span></div><div class="criteria">${icon('check')}<span>运行时回退与已上线产品恢复分别处理。</span></div>`,button('明白了','close-overlay','primary'));break;
 case 'release-recovery':modal('恢复上一部署版本','先核对当前发布与数据兼容条件，再执行恢复。',`<p class="small muted">示例方案：切回已验证的 v0.9.11 制品，观察核心导入流程。真实客户端还需核对本轮是否包含不可逆的数据变更。</p><div class="help-box" style="margin-top:17px">此处只演示交互，不会操作真实部署、代码或数据。</div>`,`${button('关闭','close-overlay')}${button('演示恢复','confirm-recovery','','history')}`);break;
 case 'confirm-recovery':state.releaseRestored=true;persist();closeOverlay();render();toast('已演示恢复上一制品；未触发真实部署。');break;
 case 'about':modal('航向 Vela · 桌面交互原型','人掌握方向，AI 持续推进。',`<p class="small muted">当前页面用于体验整体 UI、信息架构与桌面生命周期。所有数据、执行、验证、发布与恢复均为示例。</p><div class="separator"></div><p class="small muted">原型不会访问目录、运行代码、调用模型或修改系统设置。它只在当前浏览器中保存方向、主题和演示状态。</p>`,`${button('查看完整设计','about-design','','info')}${button('继续体验','close-overlay','primary')}`);break;
 case 'about-design':closeOverlay();view='notes';render();break;
 case 'reset-demo':modal('恢复初始示例？','这只清除当前浏览器中的原型状态。',`<p class="small muted">已编辑的示例方向、新增的示例项目、主题和演示运行包将恢复初始值。真实文件与账号不受影响。</p>`,`${button('取消','close-overlay')}${button('恢复示例','confirm-reset','danger','refresh')}`);break;
 case 'confirm-reset':state=structuredClone(initial);initHarnessState();view='workbench';persist();closeOverlay();render();toast('已恢复初始示例。');break;
 default:handleHarnessAction(el);break;
 }
}
document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(el){handleAction(el);return;}if(event.target.matches('[data-backdrop="close"]'))closeOverlay();if(projectMenu&&!event.target.closest('.project-popover,.workspace-switch')){projectMenu=false;render();}});
document.addEventListener('submit',event=>{if(event.target.id==='direction-form'){event.preventDefault();const d=new FormData(event.target);const goal=String(d.get('direction')||'').trim();const budget=Number(d.get('budget'));if(!goal||budget<15||budget>10000){document.getElementById('direction-error').textContent='请填写产品方向，并将示例预算设为 15 到 10000 元。';return;}const p=project();p.direction=goal;p.detail=String(d.get('detail')||'').trim();p.version++;state.budget=budget;p.budget=budget;persist();closeOverlay();render();toast('方向版本 v'+p.version+' 已保存，AI 将据此重新规划。');}
if(event.target.id==='project-form'){event.preventDefault();const d=new FormData(event.target);const name=String(d.get('name')||'').trim(),path=String(d.get('path')||'').trim(),direction=String(d.get('direction')||'').trim();if(!name||!path||!direction){document.getElementById('project-error').textContent='请完整填写项目名称、示例位置与方向。';return;}const id='project-'+Date.now();state.projects.push({id,name,path,direction,detail:'先调查项目现状，再自主选择值得推进的工作。',version:1,isNew:true});state.activeProject=id;persist();closeOverlay();view='overview';render();toast('示例项目已创建；未读取本地文件，研发内容仍为原型示例。');}
if(event.target.id==='strategic-form'){event.preventDefault();const value=new FormData(event.target).get('strategy');state.directionAnswered=true;project().version++;if(value==='explore')project().detail='优先解决现有导入障碍；允许调查图片识别方案，启用外部服务前明确授权。';persist();closeOverlay();render();toast(value==='explore'?'方向已更新：允许调研，尚未启用任何付费服务。':'方向已更新：保持现有范围与预算。');}});
document.addEventListener('change',event=>{const el=event.target;if(!el.dataset.setting)return;const k=el.dataset.setting;if(k==='budget'){const n=Number(el.value);if(!Number.isFinite(n)||n<15||n>10000){toast('示例预算应为 15 到 10000 元。');el.value=state.budget;return;}state.budget=n;project().budget=n;}else state.settings[k]=el.type==='checkbox'?el.checked:el.value;persist();applyTheme();render();toast(k==='theme'?'外观已更新。':k==='autostart'?'启动偏好已保存；未修改系统登录项。':'偏好已保存。');});
document.addEventListener('input',event=>{if(event.target.id==='command-input')document.getElementById('palette-results').innerHTML=paletteResults(event.target.value);});
document.addEventListener('keydown',event=>{if(event.isComposing)return;if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();if(overlay==='command')closeOverlay();else if(!background&&!exited)commandPalette();}if(event.key==='Escape'){if(overlay)closeOverlay();else if(projectMenu){projectMenu=false;render();}}if(event.key==='Tab'&&overlay){const nodes=[...document.querySelectorAll('#overlay-root button:not(:disabled),#overlay-root input:not(:disabled),#overlay-root textarea:not(:disabled),#overlay-root select:not(:disabled),#overlay-root a[href]')].filter(n=>n.getClientRects().length);if(!nodes.length)return;const first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if(state.settings.theme==='system')applyTheme();});
render();

function newProjectOverview(){const p=project();return `${pageHeading('先理解项目，再开始推进。','示例项目已建立。原生客户端接入环境后，AI 会先调查现状并建立基线。',button('调整方向','edit-direction','primary','compass'),'NEW PROJECT')}<section class="card direction-card"><div class="eyebrow">当前方向 · v${p.version}</div><div class="direction-title">${esc(p.direction)}</div><p class="direction-copy">${esc(p.detail)}</p><div class="direction-foot">${button('查看接入准备','project-setup-info','','folder')}<span class="direction-tag">未读取本地文件</span></div></section><section class="card card-pad" style="margin-top:22px"><h2>项目接入准备</h2><div class="criteria">${icon('check')}<span>项目名称与方向已保存为原型状态。</span></div><div class="criteria">${icon('clock')}<span>等待原生客户端的目录授权与环境连接。</span></div><div class="criteria">${icon('clock')}<span>完成调查后，展示候选决策、研发工作和交付记录。</span></div><div class="help-box">新项目保持独立状态，不复用其他项目的研发与交付数据。</div></section>`;}
function emptyProjectPage(){return `${view==='decisions'?projectLeads():''}${pageHeading(labels[view],'新项目尚未产生相关记录，完成项目调查后会在这里展示。','','PROJECT SETUP')}<section class="card empty">${icon('folder')}<p style="margin-top:13px">${esc(project().name)} 尚未产生${labels[view]}记录。</p><p class="tiny muted">原型未连接真实执行环境，暂不生成模拟研发结论。</p><div style="margin-top:16px">${button('查看接入准备','project-setup-info','','arrow')}</div></section>`;}
